let pendingRender=0;input.addEventListener('input',()=>{cancelAnimationFrame(pendingRender);pendingRender=requestAnimationFrame(render);});input.addEventListener('compositionend',()=>{cancelAnimationFrame(pendingRender);pendingRender=requestAnimationFrame(render);});input.addEventListener('keydown',e=>{if(e.key==='Escape'){input.value='';render();return;}if(!links.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+links.length)%links.length;links[active].focus();}else if(e.key==='Enter'){e.preventDefault();links[0].click();}});wrap.addEventListener('keydown',e=>{if(e.key==='Escape'){input.focus();return;}if(e.key!=='ArrowDown'&&e.key!=='ArrowUp')return;e.preventDefault();active=(links.indexOf(document.activeElement)+(e.key==='ArrowDown'?1:-1)+links.length)%links.length;links[active].focus();});render();
